const editor=element('dialog','<h2>自分の言葉に、直す。</h2><form id="ux-edit-form"><label for="ux-edit-field">変更・補足すること</label><select id="ux-edit-field"></select><label for="ux-edit-value">内容</label><textarea id="ux-edit-value" maxlength="2000" rows="4"></textarea><label for="ux-edit-quote">会話の言葉をそのまま使う（任意）</label><select id="ux-edit-quote"><option value="">自分で書く</option></select><div class="form-actions"><button class="primary" type="submit">候補へ反映</button><button type="button" id="ux-edit-cancel">戻る</button></div></form>');editor.setAttribute('aria-label','候補の変更');document.body.append(editor);let editing=null;
