function openTalk(kind,planId){const records=B.records(),plan=records.find(r=>r.id===planId&&r.kind==='plan');if(kind==='experience'){$('ux-reflection-plan').value=plan?.id||'';go('experiences');$('ux-reflection').focus();return}const texts={aspiration:'ありたい姿はまだ分からない。気になっていることから話してみたい。',plan:'この会話で分かったことを、希望する範囲で試す方法を考えたい。まだ採用は決めていない。'};go('dialogue');$('chat-input').value=texts[kind];$('chat-input').dispatchEvent(new Event('input',{bubbles:true}));$('chat-input').focus();}
