document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.action==='reflect'){e.preventDefault();e.stopImmediatePropagation();openTalk('experience',button.dataset.id);}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.uxTalk)openTalk(b.dataset.uxTalk);if(b.dataset.uxMessage)openOrganizer('aspiration',b.dataset.uxMessage);if(b.dataset.action?.startsWith('edit-')){const kind=b.dataset.action.slice(5);if(manual[kind])manual[kind].open=true;}const id=b.dataset.uxDraft,action=b.dataset.uxAction;if(!id)return;try{if(action==='edit')return editDraft(id);if(action==='adopt'||action==='pause'){const confirmed=$('ux-confirm-'+id).checked;B.saveDraft(id,confirmed,action==='pause'?'paused':'selected');B.notify('本人が確認した内容だけを残しました。AIへの共有は、別に選べます。');return}B.changeDraft(id,d=>{d.status=action==='hold'?'held':action==='restore'?'candidate':'deleted'});B.notify(action==='hold'?'候補を保留しました。計画は確定していません。':action==='restore'?'候補を戻しました。':'候補を削除しました。記憶画面から戻せます。');}catch(err){B.notify(err.message)}});
