for(const kind of Object.keys(destinations)){const drafts=B.state().drafts.filter(d=>d.kind===kind&&!['adopted','deleted'].includes(d.status));$('ux-'+kind+'-drafts').innerHTML=drafts.length?drafts.map(d=>{const primary=d.values.text||d.values.title||d.values.actual;return '<article class="conversation-draft"><p class="eyebrow">'+(d.status==='held'?'いまは保留':d.status==='stale'?'訂正前の候補・再確認が必要':'まだ、自分で確かめる前の候補')+'</p><h2>'+esc(primary)+'</h2><p class="quiet">'+(d.origin.startsWith('ai-')?'AIが出した未確認の案。':'本人が選んだ発言からの候補。')+'確定した事実や、採用した行動ではありません。</p>'+(kind==='plan'?'<dl class="draft-facts">'+['reason','when','amount'].map(k=>'<div><dt>'+names[k]+'</dt><dd>'+esc(d.values[k]||'まだ決めなくていい')+'</dd></div>').join('')+'<p class="quiet">時・量は会話内の表現の抜き出し案です。意味の理解や適切さは未検証。自分で変更できます。</p>':'')+'<details><summary>もとの言葉と、未確認の情報</summary>'+d.evidence.map(v=>'<blockquote>'+esc(v.quote)+'</blockquote>').join('')+'<p>外部の記録ではありません。未記入の情報を推測で埋めません。</p></details><label class="check-label"><input id="ux-confirm-'+d.id+'" type="checkbox" '+(d.status==='stale'?'disabled':'')+'>内容を確かめ、自分の言葉・選択として残したい</label><div class="form-actions"><button class="primary" type="button" data-ux-draft="'+d.id+'" data-ux-action="adopt" '+(d.status==='stale'?'disabled':'')+'>'+(kind==='plan'?'自分で選んで、試すことにする':'確認して残す')+'</button><button type="button" data-ux-draft="'+d.id+'" data-ux-action="edit">変更・必要なことだけ補足</button><button type="button" data-ux-draft="'+d.id+'" data-ux-action="hold">今は保留</button>'+(kind==='plan'?'<button type="button" data-ux-draft="'+d.id+'" data-ux-action="pause">休止して残す</button>':'')+'<button class="link-button" type="button" data-ux-draft="'+d.id+'" data-ux-action="delete">この候補を削除</button></div></article>'}).join(''):'<p class="empty ux-empty">'+(kind==='aspiration'?'まだ決まっていなくても大丈夫。対話で見つかった言葉を、必要なときにここへ。':kind==='plan'?'今は試すことを決めなくてもいい。対話から選んだ候補だけが、ここに並びます。':'振り返りの言葉を残すかどうかも、自分で選べます。')+'</p>';}
const values=B.records();$('ux-memory-summary').innerHTML='<p><strong>'+values.length+'件</strong> の確認済み記録 / 未確認・保留の候補 '+B.state().drafts.filter(d=>['candidate','held'].includes(d.status)).length+'件（共有には含めません）</p>'+values.map(r=>'<p><span class="meta">'+labels[r.kind]+' / 本人確認・外部未確認</span><br>'+esc(r.values.text||r.values.title||r.values.actual)+' <a href="#'+destinations[r.kind]+'">訂正・削除</a></p>').join('')+B.state().drafts.filter(d=>d.status==='deleted').map(d=>'<p>削除した候補：'+esc(d.values.text||d.values.title||d.values.actual)+' <button type="button" data-ux-draft="'+d.id+'" data-ux-action="restore">この候補を戻す</button></p>').join('');
const keep=$('ux-reflection-plan').value;$('ux-reflection-plan').innerHTML='<option value="">関連付けずに話す</option>'+values.filter(r=>r.kind==='plan').map(r=>'<option value="'+r.id+'">'+esc(r.values.title)+'</option>').join('');if(values.some(r=>r.id===keep))$('ux-reflection-plan').value=keep;
$('ux-status').textContent=live?.runtime.mode==='fixture'?'操作試験中・実AIではありません':live?.status==='held'?'この会話は保留中。再開するか、今日はここまででも。':live?.status==='ended'?'今日はここまで。新しく話すこともできます。':'話すだけでも、結論を聞くだけでも。';
const currentMessages=live?.messages||[];[...$('live-log').querySelectorAll('.chat-message')].forEach((node,i)=>{const m=currentMessages[i];if(!m)return;if(m.role==='user'&&m.status==='current'&&!node.querySelector('[data-ux-message]')){const b=element('button','この言葉を残す','link-button');b.type='button';b.dataset.uxMessage=m.id;(node.querySelector('.message-detail')||node).append(b)}const meta=[...node.children].filter(x=>x.classList.contains('meta'));if(meta.length>1){const d=element('details','<summary>応答の情報</summary>','response-details');node.append(d);meta.slice(1).forEach(x=>d.append(x))}});
